-- Import for Juz 1, Package A
BEGIN;
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('ed20084a-b7e5-4603-99fe-afcab5bf7c0c', 1, 'A', 1, 1, 'multiple_choice', 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '["\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0671\u0644\u0621\u064e\u0627\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e", "\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0648\u064e\u0628\u0650\u0671\u0644\u0652\u0621\u064e\u0627\u062e\u0650\u0631\u064e\u0629\u0650 \u0647\u064f\u0645\u0652 \u064a\u064f\u0648\u0642\u0650\u0646\u064f\u0648\u0646\u064e"]'::jsonb, 'ٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلءَاخِرَةِ هُمْ يُوقِنُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('1eda7448-a94c-4192-bc01-fbabaca454ca', 1, 'A', 1, 2, 'multiple_choice', 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '["\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u06df \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0621\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0646\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e", "\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u06df \u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0621\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0646\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e"]'::jsonb, 'وَٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('5ebd23a9-e31b-4c3f-a063-d52895cdea9d', 1, 'A', 1, 3, 'multiple_choice', 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَٰلِدُونَ', '["\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0670\u062a\u064b\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0670\u0643\u064f\u0645\u0652 \u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e", "\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u0649\u0650\u06e6\u0653 \u0623\u064e\u0646 \u064a\u064e\u0636\u0652\u0631\u0650\u0628\u064e \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u0645\u0651\u064e\u0627 \u0628\u064e\u0639\u064f\u0648\u0636\u064e\u0629\u064b \u0641\u064e\u0645\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0647\u064e\u0627 \u06da \u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u06df \u0641\u064e\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0671\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u06df \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0645\u064e\u0627\u0630\u064e\u0627\u0653 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u064e\u062b\u064e\u0644\u064b\u0627 \u06d8 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u064a\u064e\u0647\u0652\u062f\u0650\u0649 \u0628\u0650\u0647\u0650\u06e6 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0636\u0650\u0644\u0651\u064f \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0652\u0641\u064e\u0670\u0633\u0650\u0642\u0650\u064a\u0646\u064e"]'::jsonb, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('2f8128cb-8955-48be-b433-a333aa4c0595', 1, 'A', 1, 4, 'multiple_choice', 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', '["\u0641\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u064d \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f", "\u0641\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u064d \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f"]'::jsonb, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('e5ee9a25-6f21-4ad9-be03-6e9cb8a648fa', 1, 'A', 1, 5, 'multiple_choice', 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '["\u0648\u064e\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u06df \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u0652\u062a\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u06df \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u064d\u06ed \u0628\u0650\u0647\u0650\u06e6 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627\u06df \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0649 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650", "\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u06df \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u06df \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u06df\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e"]'::jsonb, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('8d4a44d2-fd83-4529-ad55-46ce8d39192e', 1, 'A', 1, 6, 'multiple_choice', 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', '["\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0644\u0652\u0628\u0650\u0633\u064f\u0648\u0627\u06df \u0671\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0628\u0650\u0671\u0644\u0652\u0628\u064e\u0670\u0637\u0650\u0644\u0650 \u0648\u064e\u062a\u064e\u0643\u0652\u062a\u064f\u0645\u064f\u0648\u0627\u06df \u0671\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627\u06df \u0648\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0627\u06df \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0646\u064e\u0627\u0653 \u0623\u064f\u0648\u06df\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0670\u0628\u064f \u0671\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e"]'::jsonb, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('137b7d90-d07f-4c8f-b0ec-892e741ab8e8', 1, 'A', 1, 7, 'multiple_choice', 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '["\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0641\u064e\u0648\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e", "\u062b\u064f\u0645\u0651\u064e \u0628\u064e\u0639\u064e\u062b\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0648\u0652\u062a\u0650\u0643\u064f\u0645\u0652 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e"]'::jsonb, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('a5ab3558-5d84-406b-a9c4-c6319a2586fa', 1, 'A', 1, 8, 'multiple_choice', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', '["\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u0649\u0653 \u0625\u0650\u0633\u0652\u0631\u064e\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627\u06df \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u0649\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u0649\u0653 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0648\u0652\u0641\u064f\u0648\u0627\u06df \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0649\u0653 \u0623\u064f\u0648\u0641\u0650 \u0628\u0650\u0639\u064e\u0647\u0652\u062f\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u0650", "\u064a\u064e\u0670\u0628\u064e\u0646\u0650\u0649\u0653 \u0625\u0650\u0633\u0652\u0631\u064e\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0671\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627\u06df \u0646\u0650\u0639\u0652\u0645\u064e\u062a\u0650\u0649\u064e \u0671\u0644\u0651\u064e\u062a\u0650\u0649\u0653 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u0651\u0650\u0649 \u0641\u064e\u0636\u0651\u064e\u0644\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0671\u0644\u0652\u0639\u064e\u0670\u0644\u064e\u0645\u0650\u064a\u0646\u064e"]'::jsonb, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('e87d3e07-7063-439f-9ede-3cbd573edb04', 1, 'A', 1, 9, 'multiple_choice', 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', '["\u0648\u064e\u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u06df \u0628\u0650\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u0652\u062a\u064f \u0645\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064b\u0627 \u0644\u0651\u0650\u0645\u064e\u0627 \u0645\u064e\u0639\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0653\u0627\u06df \u0623\u064e\u0648\u0651\u064e\u0644\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u064d\u06ed \u0628\u0650\u0647\u0650\u06e6 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627\u06df \u0628\u0650\u0640\u0654\u064e\u0627\u064a\u064e\u0670\u062a\u0650\u0649 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650", "\u0648\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0627\u06df \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u0651\u064e\u0627 \u062a\u064e\u062c\u0652\u0632\u0650\u0649 \u0646\u064e\u0641\u0652\u0633\u064c \u0639\u064e\u0646 \u0646\u0651\u064e\u0641\u0652\u0633\u064d \u0634\u064e\u064a\u0652\u0640\u0654\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0628\u064e\u0644\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0634\u064e\u0641\u064e\u0670\u0639\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u062e\u064e\u0630\u064f \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0639\u064e\u062f\u0652\u0644\u064c \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e"]'::jsonb, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('f1c3c916-427a-4fb3-b67b-7a611315516b', 1, 'A', 1, 10, 'multiple_choice', 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', '["\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e"]'::jsonb, 'أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('7932af98-3314-4d61-ac0a-f14929a3efe6', 1, 'A', 1, 11, 'multiple_choice', 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ', '["\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u0623\u064e\u0644\u064e\u0627\u0653 \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0647\u064f\u0645\u064f \u0671\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0644\u0651\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e"]'::jsonb, 'أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('b8e501d9-42be-4752-8be1-f3089041c004', 1, 'A', 1, 12, 'multiple_choice', 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', '["\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u062a\u064f\u0641\u0652\u0633\u0650\u062f\u064f\u0648\u0627\u06df \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u06df \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0645\u064f\u0635\u0652\u0644\u0650\u062d\u064f\u0648\u0646\u064e", "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u0650\u064a\u0644\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u0621\u064e\u0627\u0645\u0650\u0646\u064f\u0648\u0627\u06df \u0643\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u06df \u0623\u064e\u0646\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0643\u064e\u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0671\u0644\u0633\u0651\u064f\u0641\u064e\u0647\u064e\u0627\u0653\u0621\u064f"]'::jsonb, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('c501ef74-4e89-4288-b30e-086e3dc69bd2', 1, 'A', 1, 13, 'multiple_choice', 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', '["\u0623\u064f\u0648\u06df\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0671\u0634\u0652\u062a\u064e\u0631\u064e\u0648\u064f\u0627\u06df \u0671\u0644\u0636\u0651\u064e\u0644\u064e\u0670\u0644\u064e\u0629\u064e \u0628\u0650\u0671\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0641\u064e\u0645\u064e\u0627 \u0631\u064e\u0628\u0650\u062d\u064e\u062a \u062a\u0651\u0650\u062c\u064e\u0670\u0631\u064e\u062a\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u06df \u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e", "\u0623\u064e\u0648\u0652 \u0643\u064e\u0635\u064e\u064a\u0651\u0650\u0628\u064d \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0641\u0650\u064a\u0647\u0650 \u0638\u064f\u0644\u064f\u0645\u064e\u0670\u062a\u064c \u0648\u064e\u0631\u064e\u0639\u0652\u062f\u064c \u0648\u064e\u0628\u064e\u0631\u0652\u0642\u064c \u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0646\u064e \u0623\u064e\u0635\u064e\u0670\u0628\u0650\u0639\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u0649\u0653 \u0621\u064e\u0627\u0630\u064e\u0627\u0646\u0650\u0647\u0650\u0645 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u0648\u064e\u0670\u0639\u0650\u0642\u0650 \u062d\u064e\u0630\u064e\u0631\u064e \u0671\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650 \u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064f\u062d\u0650\u064a\u0637\u064c\u06e2 \u0628\u0650\u0671\u0644\u0652\u0643\u064e\u0670\u0641\u0650\u0631\u0650\u064a\u0646\u064e"]'::jsonb, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('acd5bd97-b963-4e6d-85d5-1f0612285caf', 1, 'A', 1, 14, 'multiple_choice', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '["\u0641\u0650\u0649 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645 \u0645\u0651\u064e\u0631\u064e\u0636\u064c \u0641\u064e\u0632\u064e\u0627\u062f\u064e\u0647\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0631\u064e\u0636\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c\u06e2 \u0628\u0650\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627\u06df \u064a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0648\u0646\u064e", "\u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u0631\u064e\u0670\u0634\u064b\u0627 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0653\u0621\u064b \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627\u06df \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"]'::jsonb, 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('a97f1425-cfb3-427b-9e5d-0438b9f601f6', 1, 'A', 1, 15, 'multiple_choice', 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', '["\u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0651\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u0643\u0652\u062a\u064f\u0628\u064f\u0648\u0646\u064e \u0671\u0644\u0652\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0628\u0650\u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u062f\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0644\u0650\u064a\u064e\u0634\u0652\u062a\u064e\u0631\u064f\u0648\u0627\u06df \u0628\u0650\u0647\u0650\u06e6 \u062b\u064e\u0645\u064e\u0646\u064b\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0641\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0648\u064e\u064a\u0652\u0644\u064c \u0644\u0651\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0643\u0652\u0633\u0650\u0628\u064f\u0648\u0646\u064e", "\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0652\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u0649\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e"]'::jsonb, 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('a9209478-1b8c-446a-9b7f-576a91c6252d', 1, 'A', 1, 16, 'multiple_choice', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627\u06df \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0671\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0627\u06df \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u06df \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0648\u064e\u0639\u064e\u0635\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064f\u0634\u0652\u0631\u0650\u0628\u064f\u0648\u0627\u06df \u0641\u0650\u0649 \u0642\u064f\u0644\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0671\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0628\u0650\u0643\u064f\u0641\u0652\u0631\u0650\u0647\u0650\u0645\u0652 \u06da \u0642\u064f\u0644\u0652 \u0628\u0650\u0626\u0652\u0633\u064e\u0645\u064e\u0627 \u064a\u064e\u0623\u0652\u0645\u064f\u0631\u064f\u0643\u064f\u0645 \u0628\u0650\u0647\u0650\u06e6\u0653 \u0625\u0650\u064a\u0645\u064e\u0670\u0646\u064f\u0643\u064f\u0645\u0652 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e \u0628\u064e\u0646\u0650\u0649\u0653 \u0625\u0650\u0633\u0652\u0631\u064e\u0670\u0653\u0621\u0650\u064a\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0628\u0650\u0671\u0644\u0652\u0648\u064e\u0670\u0644\u0650\u062f\u064e\u064a\u0652\u0646\u0650 \u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0630\u0650\u0649 \u0671\u0644\u0652\u0642\u064f\u0631\u0652\u0628\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0652\u064a\u064e\u062a\u064e\u0670\u0645\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0652\u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u0650 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u06df \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u064f\u0633\u0652\u0646\u064b\u0627 \u0648\u064e\u0623\u064e\u0642\u0650\u064a\u0645\u064f\u0648\u0627\u06df \u0671\u0644\u0635\u0651\u064e\u0644\u064e\u0648\u0670\u0629\u064e \u0648\u064e\u0621\u064e\u0627\u062a\u064f\u0648\u0627\u06df \u0671\u0644\u0632\u0651\u064e\u0643\u064e\u0648\u0670\u0629\u064e \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0639\u0652\u0631\u0650\u0636\u064f\u0648\u0646\u064e"]'::jsonb, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('363413e3-82a0-41fe-bca7-fe9f6747bcd6', 1, 'A', 1, 17, 'multiple_choice', 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '["\u062b\u064f\u0645\u0651\u064e \u0642\u064e\u0633\u064e\u062a\u0652 \u0642\u064f\u0644\u064f\u0648\u0628\u064f\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0647\u0650\u0649\u064e \u0643\u064e\u0671\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0623\u064e\u0648\u0652 \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0642\u064e\u0633\u0652\u0648\u064e\u0629\u064b \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0652\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u0650 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0641\u064e\u062c\u0651\u064e\u0631\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0671\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0670\u0631\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0634\u0651\u064e\u0642\u0651\u064e\u0642\u064f \u0641\u064e\u064a\u064e\u062e\u0652\u0631\u064f\u062c\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0671\u0644\u0652\u0645\u064e\u0627\u0653\u0621\u064f \u06da \u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0644\u064e\u0645\u064e\u0627 \u064a\u064e\u0647\u0652\u0628\u0650\u0637\u064f \u0645\u0650\u0646\u0652 \u062e\u064e\u0634\u0652\u064a\u064e\u0629\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u06d7 \u0648\u064e\u0645\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u063a\u064e\u0670\u0641\u0650\u0644\u064d \u0639\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e", "\u0623\u064e\u0641\u064e\u062a\u064e\u0637\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0646 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627\u06df \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0627\u0646\u064e \u0641\u064e\u0631\u0650\u064a\u0642\u064c \u0645\u0651\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e \u0643\u064e\u0644\u064e\u0670\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u064f\u0648\u0646\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0639\u064e\u0642\u064e\u0644\u064f\u0648\u0647\u064f \u0648\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"]'::jsonb, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('6b0bc257-f303-4052-b754-98f20008196d', 1, 'A', 1, 18, 'multiple_choice', 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ', '["\u0623\u064e\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0623\u064e\u0646\u0651\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e", "\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u06df \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u06df \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0670\u0628\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0671\u0644\u0652\u0621\u064e\u0627\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e"]'::jsonb, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('4e978afd-213d-4d8b-b78f-677462a112c5', 1, 'A', 1, 19, 'multiple_choice', 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0648\u064e\u0670\u0639\u064e\u062f\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670\u0653 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u0644\u064e\u064a\u0652\u0644\u064e\u0629\u064b \u062b\u064f\u0645\u0651\u064e \u0671\u062a\u0651\u064e\u062e\u064e\u0630\u0652\u062a\u064f\u0645\u064f \u0671\u0644\u0652\u0639\u0650\u062c\u0652\u0644\u064e \u0645\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u06e6 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0638\u064e\u0670\u0644\u0650\u0645\u064f\u0648\u0646\u064e", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u0649 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u064c \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c"]'::jsonb, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('bac680a6-638f-443c-9c37-7e282db7d61c', 1, 'A', 1, 20, 'multiple_choice', 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَٰفِرِينَ', '["\u0648\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0650 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u06df \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627\u06df \u0671\u0644\u0635\u0651\u064e\u0670\u0644\u0650\u062d\u064e\u0670\u062a\u0650 \u0623\u064e\u0646\u0651\u064e \u0644\u064e\u0647\u064f\u0645\u0652 \u062c\u064e\u0646\u0651\u064e\u0670\u062a\u064d \u062a\u064e\u062c\u0652\u0631\u0650\u0649 \u0645\u0650\u0646 \u062a\u064e\u062d\u0652\u062a\u0650\u0647\u064e\u0627 \u0671\u0644\u0652\u0623\u064e\u0646\u0652\u0647\u064e\u0670\u0631\u064f \u06d6 \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u0631\u064f\u0632\u0650\u0642\u064f\u0648\u0627\u06df \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0645\u0650\u0646 \u062b\u064e\u0645\u064e\u0631\u064e\u0629\u064d \u0631\u0651\u0650\u0632\u0652\u0642\u064b\u0627 \u06d9 \u0642\u064e\u0627\u0644\u064f\u0648\u0627\u06df \u0647\u064e\u0670\u0630\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u0631\u064f\u0632\u0650\u0642\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0648\u064e\u0623\u064f\u062a\u064f\u0648\u0627\u06df \u0628\u0650\u0647\u0650\u06e6 \u0645\u064f\u062a\u064e\u0634\u064e\u0670\u0628\u0650\u0647\u064b\u0627 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627\u0653 \u0623\u064e\u0632\u0652\u0648\u064e\u0670\u062c\u064c \u0645\u0651\u064f\u0637\u064e\u0647\u0651\u064e\u0631\u064e\u0629\u064c \u06d6 \u0648\u064e\u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0670\u0644\u0650\u062f\u064f\u0648\u0646\u064e", "\u0648\u064e\u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0641\u0650\u0649 \u0631\u064e\u064a\u0652\u0628\u064d \u0645\u0651\u0650\u0645\u0651\u064e\u0627 \u0646\u064e\u0632\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u064e\u0628\u0652\u062f\u0650\u0646\u064e\u0627 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627\u06df \u0628\u0650\u0633\u064f\u0648\u0631\u064e\u0629\u064d \u0645\u0651\u0650\u0646 \u0645\u0651\u0650\u062b\u0652\u0644\u0650\u0647\u0650\u06e6 \u0648\u064e\u0671\u062f\u0652\u0639\u064f\u0648\u0627\u06df \u0634\u064f\u0647\u064e\u062f\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0635\u064e\u0670\u062f\u0650\u0642\u0650\u064a\u0646\u064e"]'::jsonb, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَٰلِدُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('990e2c8c-7862-41fe-aa05-7728c997f8e5', 1, 'A', 1, 21, 'multiple_choice', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '["\u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0630\u064e\u0644\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0671\u0645\u0652\u0634\u064f\u0648\u0627\u06df \u0641\u0650\u0649 \u0645\u064e\u0646\u064e\u0627\u0643\u0650\u0628\u0650\u0647\u064e\u0627 \u0648\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u06df \u0645\u0650\u0646 \u0631\u0651\u0650\u0632\u0652\u0642\u0650\u0647\u0650\u06e6 \u06d6 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0671\u0644\u0646\u0651\u064f\u0634\u064f\u0648\u0631\u064f", "\u0671\u0644\u0651\u064e\u0630\u0650\u0649 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u0650\u0631\u064e\u0670\u0634\u064b\u0627 \u0648\u064e\u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u064e \u0628\u0650\u0646\u064e\u0627\u0653\u0621\u064b \u0648\u064e\u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0653\u0621\u0650 \u0645\u064e\u0627\u0653\u0621\u064b \u0641\u064e\u0623\u064e\u062e\u0652\u0631\u064e\u062c\u064e \u0628\u0650\u0647\u0650\u06e6 \u0645\u0650\u0646\u064e \u0671\u0644\u062b\u0651\u064e\u0645\u064e\u0631\u064e\u0670\u062a\u0650 \u0631\u0650\u0632\u0652\u0642\u064b\u0627 \u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627\u06df \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u0646\u062f\u064e\u0627\u062f\u064b\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"]'::jsonb, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('b75a9218-70b4-47a7-ae86-4ecaafc4c529', 1, 'A', 1, 22, 'multiple_choice', 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u0649 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u064c \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c", "\u0625\u0650\u0646\u0651\u064e \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u06df \u0648\u064e\u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062f\u064f\u0648\u0627\u06df \u0648\u064e\u0671\u0644\u0646\u0651\u064e\u0635\u064e\u0670\u0631\u064e\u0649\u0670 \u0648\u064e\u0671\u0644\u0635\u0651\u064e\u0670\u0628\u0650\u0640\u0654\u0650\u064a\u0646\u064e \u0645\u064e\u0646\u0652 \u0621\u064e\u0627\u0645\u064e\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0671\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0671\u0644\u0652\u0621\u064e\u0627\u062e\u0650\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0670\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0644\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u062c\u0652\u0631\u064f\u0647\u064f\u0645\u0652 \u0639\u0650\u0646\u062f\u064e \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e"]'::jsonb, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('4a8171b0-e6f0-4cad-85dc-7aeb436e4239', 1, 'A', 1, 23, 'multiple_choice', 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u0649 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u064c \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u0649 \u062c\u064e\u0627\u0639\u0650\u0644\u064c \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u06df \u0623\u064e\u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u0641\u0650\u0643\u064f \u0671\u0644\u062f\u0651\u0650\u0645\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0646\u064f\u0642\u064e\u062f\u0651\u0650\u0633\u064f \u0644\u064e\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u0649\u0653 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"]'::jsonb, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('ec25b36f-2ed4-4099-b49c-21301a67c9a5', 1, 'A', 1, 24, 'multiple_choice', 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ', '["\u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e"]'::jsonb, 'يَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('1147cf2d-7d60-4043-8d44-ef5caa42890a', 1, 'A', 1, 25, 'multiple_choice', 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ ۖ وَلَهُمْ', '["\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u064c", "\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0639\u064e\u0638\u0650\u064a\u0645\u064c"]'::jsonb, 'عَذَابٌ أَلِيمٌ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('648f6837-fcfb-492c-a9c2-aee278b86d04', 1, 'A', 1, 26, 'multiple_choice', 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ ۖ وَلَهُمْ
يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ', '["\u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650", "\u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u0650"]'::jsonb, 'وَإِيَّٰىَ فَٱتَّقُونِ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('957c730f-33a5-4c45-8290-8b008b72e654', 1, 'A', 1, 27, 'multiple_choice', 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ ۖ وَلَهُمْ
يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ', '["\u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u0650", "\u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0670\u0649\u064e \u0641\u064e\u0671\u0631\u0652\u0647\u064e\u0628\u064f\u0648\u0646\u0650"]'::jsonb, 'وَإِيَّٰىَ فَٱتَّقُونِ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('8c138be2-1781-4f65-b1c2-b24bd5b4ae8b', 1, 'A', 1, 28, 'multiple_choice', 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ', '["\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e"]'::jsonb, 'تَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('b24ae2df-9d53-40cf-8f05-5c1a2c254a10', 1, 'A', 1, 29, 'multiple_choice', 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ', '["\u062a\u064e\u0646\u0638\u064f\u0631\u064f\u0648\u0646\u064e", "\u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e"]'::jsonb, 'تَنظُرُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('eff5c60e-8553-4f68-8699-d5c938b65167', 1, 'A', 1, 30, 'multiple_choice', 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0644\u0650\u0644\u0652\u0645\u064e\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e\u0629\u0650 \u0625\u0650\u0646\u0651\u0650\u0649 \u062c\u064e\u0627\u0639\u0650\u0644\u064c \u0641\u0650\u0649 \u0671\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062e\u064e\u0644\u0650\u064a\u0641\u064e\u0629\u064b \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u06df \u0623\u064e\u062a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0645\u064e\u0646 \u064a\u064f\u0641\u0652\u0633\u0650\u062f\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u064a\u064e\u0633\u0652\u0641\u0650\u0643\u064f \u0671\u0644\u062f\u0651\u0650\u0645\u064e\u0627\u0653\u0621\u064e \u0648\u064e\u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u0633\u064e\u0628\u0651\u0650\u062d\u064f \u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0643\u064e \u0648\u064e\u0646\u064f\u0642\u064e\u062f\u0651\u0650\u0633\u064f \u0644\u064e\u0643\u064e \u06d6 \u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u0649\u0653 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0646\u064e\u062c\u0651\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0621\u064e\u0627\u0644\u0650 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u064a\u064e\u0633\u064f\u0648\u0645\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u0633\u064f\u0648\u0653\u0621\u064e \u0671\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u064a\u064f\u0630\u064e\u0628\u0651\u0650\u062d\u064f\u0648\u0646\u064e \u0623\u064e\u0628\u0652\u0646\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u064a\u064e\u0633\u0652\u062a\u064e\u062d\u0652\u064a\u064f\u0648\u0646\u064e \u0646\u0650\u0633\u064e\u0627\u0653\u0621\u064e\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0641\u0650\u0649 \u0630\u064e\u0670\u0644\u0650\u0643\u064f\u0645 \u0628\u064e\u0644\u064e\u0627\u0653\u0621\u064c \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064c", "\u0641\u064e\u062a\u064e\u0644\u064e\u0642\u0651\u064e\u0649\u0670\u0653 \u0621\u064e\u0627\u062f\u064e\u0645\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0647\u0650\u06e6 \u0643\u064e\u0644\u0650\u0645\u064e\u0670\u062a\u064d \u0641\u064e\u062a\u064e\u0627\u0628\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u06e5 \u0647\u064f\u0648\u064e \u0671\u0644\u062a\u0651\u064e\u0648\u0651\u064e\u0627\u0628\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f", "*", "\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0671\u0647\u0652\u0628\u0650\u0637\u064f\u0648\u0627\u06df \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 \u06d6 \u0641\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0651\u0650\u0649 \u0647\u064f\u062f\u064b\u0649 \u0641\u064e\u0645\u064e\u0646 \u062a\u064e\u0628\u0650\u0639\u064e \u0647\u064f\u062f\u064e\u0627\u0649\u064e \u0641\u064e\u0644\u064e\u0627 \u062e\u064e\u0648\u0652\u0641\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0648\u064e\u0644\u064e\u0627 \u0647\u064f\u0645\u0652 \u064a\u064e\u062d\u0652\u0632\u064e\u0646\u064f\u0648\u0646\u064e", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0671\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627\u06df \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0671\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064e \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627\u06df \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062d\u064e\u064a\u0652\u062b\u064f \u0634\u0650\u0626\u0652\u062a\u064f\u0645\u0652 \u0631\u064e\u063a\u064e\u062f\u064b\u0627 \u0648\u064e\u0671\u062f\u0652\u062e\u064f\u0644\u064f\u0648\u0627\u06df \u0671\u0644\u0652\u0628\u064e\u0627\u0628\u064e \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627\u06df \u062d\u0650\u0637\u0651\u064e\u0629\u064c \u0646\u0651\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652 \u062e\u064e\u0637\u064e\u0670\u064a\u064e\u0670\u0643\u064f\u0645\u0652 \u06da \u0648\u064e\u0633\u064e\u0646\u064e\u0632\u0650\u064a\u062f\u064f \u0671\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e", "\u0648\u064e\u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064f\u0645\u0651\u0650\u064a\u0651\u064f\u0648\u0646\u064e \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u0671\u0644\u0652\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0625\u0650\u0644\u0651\u064e\u0627\u0653 \u0623\u064e\u0645\u064e\u0627\u0646\u0650\u0649\u0651\u064e \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u064a\u064e\u0638\u064f\u0646\u0651\u064f\u0648\u0646\u064e", "*", "\u0648\u064e\u0625\u0650\u0630\u0652 \u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627 \u0645\u0650\u064a\u062b\u064e\u0670\u0642\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0641\u064e\u0639\u0652\u0646\u064e\u0627 \u0641\u064e\u0648\u0652\u0642\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0637\u0651\u064f\u0648\u0631\u064e \u062e\u064f\u0630\u064f\u0648\u0627\u06df \u0645\u064e\u0627\u0653 \u0621\u064e\u0627\u062a\u064e\u064a\u0652\u0646\u064e\u0670\u0643\u064f\u0645 \u0628\u0650\u0642\u064f\u0648\u0651\u064e\u0629\u064d \u0648\u064e\u0671\u0630\u0652\u0643\u064f\u0631\u064f\u0648\u0627\u06df \u0645\u064e\u0627 \u0641\u0650\u064a\u0647\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u062a\u0651\u064e\u0642\u064f\u0648\u0646\u064e"]'::jsonb, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('a7edb05e-6d14-4376-909e-a822ebd04962', 1, 'A', 1, 31, 'multiple_choice', 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ
وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '["\u0648\u064e\u0625\u0650\u0630\u0652 \u0621\u064e\u0627\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0671\u0644\u0652\u0643\u0650\u062a\u064e\u0670\u0628\u064e \u0648\u064e\u0671\u0644\u0652\u0641\u064f\u0631\u0652\u0642\u064e\u0627\u0646\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e", "\u062b\u064f\u0645\u0651\u064e \u0639\u064e\u0641\u064e\u0648\u0652\u0646\u064e\u0627 \u0639\u064e\u0646\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u06e2 \u0628\u064e\u0639\u0652\u062f\u0650 \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e"]'::jsonb, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('beeafda6-98d5-4504-89e6-9bf146a21689', 1, 'A', 2, 32, 'multiple_choice', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ
- Halaman 1
.
.
.
أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ
- Halaman 10
بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('0e09722d-97c7-466c-bf0a-c138b5b6f532', 1, 'A', 2, 33, 'multiple_choice', 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('73800bed-8b95-40d5-858f-be07cbec7e5b', 1, 'A', 2, 34, 'multiple_choice', 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('94bc263b-615f-46be-beac-46a0760d4afe', 1, 'A', 2, 35, 'multiple_choice', 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('def46eb7-6dee-44f7-8501-09244fe39887', 1, 'A', 2, 36, 'multiple_choice', 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('9c7e4d0f-2d28-48be-9612-072f7b7c49bf', 1, 'A', 2, 37, 'multiple_choice', 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('1a644842-6291-40ee-a416-41d9921278ea', 1, 'A', 2, 38, 'multiple_choice', 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
INSERT INTO public.exam_questions (id, juz_number, question_package, section_number, question_number, question_type, question_text, options, correct_answer, is_active)
VALUES ('103b26bb-5deb-48a5-bab4-34d10c93f275', 1, 'A', 2, 39, 'multiple_choice', 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', '["Halaman 10", "Halaman 9", "Halaman 8", "Halaman 7"]'::jsonb, 'Halaman 10', true);
