VALUES ('f1ac2539-deca-408e-9042-bdf2fcf608ba', 1, 'A', 2, 42, 'multiple_choice', 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', '["Halaman 6", "Halaman 5", "Halaman 4", "Halaman 3", "Halaman 2", "Halaman 1", "\u0643\u064e\u064a\u0652\u0641\u064e \u062a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0671\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0623\u064e\u0645\u0652\u0648\u064e\u0670\u062a\u064b\u0627 \u0641\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0670\u0643\u064f\u0645\u0652 \u06d6 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u0645\u0650\u064a\u062a\u064f\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u064a\u064f\u062d\u0652\u064a\u0650\u064a\u0643\u064f\u0645\u0652 \u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e"]'::jsonb, 'Halaman 6', true);
